mapper.select:
select mn.*,com.C_NAME as approvalCompanyName,us.U_NAME as approvalUserName,lead.U_NAME as approvalLeaderName from Pre_Project_Approval mn left join SYS_Company com on mn.approval_company_id = com.C_ID left join SYS_User us on mn.approval_user_id = us.U_ID left join SYS_User lead on mn.approval_leader= us.U_ID where 1=1
and likeCname(#{params.approvalCompanyName},com.C_Id)=true
and com.C_NAME like concat('%',#{params.approvalCompanyName},'%')
and mn.approval_plan_year = #{params.approvalPlanYear}
and mn.approval_project_name like concat('%',#{params.approvalProjectName},'%')
and mn.approval_project_type = #{params.approvalProjectType}
and leadv.U_NAME like concat('%',#{params.approvalProjectLeaderName},'%')
and mn.approval_project_state = #{params.approvalProjectState}
order by mn.approval_project_score desc
